describe('Registration Form Email Validation', () => {
  beforeEach(() => {
    cy.visit('/register');
  });

  it('should display error message when submitting registration form with invalid email', () => {
    // Fill in valid fields
    cy.get('[data-testid="firstName-input"]').type('John');
    cy.get('[data-testid="lastName-input"]').type('Doe');
    cy.get('[data-testid="password-input"]').type('Password123!');
    cy.get('[data-testid="confirmPassword-input"]').type('Password123!');

    // Attempt to submit with invalid email
    cy.get('[data-testid="email-input"]').type('invalid-email');
    cy.get('[data-testid="submit-button"]').click();

    // Verify error message is displayed
    cy.get('[data-testid="email-error-message"]')
      .should('be.visible')
      .should('contain', 'Please enter a valid email address');

    // Verify form was not submitted
    cy.url().should('include', '/register');
    cy.get('[data-testid="success-message"]').should('not.exist');
  });

  it('should successfully submit registration form with valid email', () => {
    // Fill in valid fields
    cy.get('[data-testid="firstName-input"]').type('Jane');
    cy.get('[data-testid="lastName-input"]').type('Smith');
    cy.get('[data-testid="email-input"]').type('jane.smith@example.com');
    cy.get('[data-testid="password-input"]').type('SecurePassword123!');
    cy.get('[data-testid="confirmPassword-input"]').type('SecurePassword123!');

    // Submit the form
    cy.get('[data-testid="submit-button"]').click();

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]')
      .should('be.visible')
      .should('contain', 'Registration successful');

    // Verify user is redirected to dashboard
    cy.url().should('include', '/dashboard');
  });
});
